data.limit_purchase;
this.xhr_.fetchJson(`/api/storefront/promotion/landing_page/product?product_id=${product_id}&discoun
t_id=${discount_id}&apply_scenario=${apply_scenario}`, { method: "get", }).then(async(res)=>{
this.handleLoading_({type: 'whole', action: 'close'}); const $quickShop = await
SPZ.whenApiDefined(document.querySelector('#apps-discount-quick-view-render')); //
定义默认渲染的子款式 const selectedVariant = res.product.variants.find((v)=> (v.available &&
